"""W55-56 item 5: PKI-signed compliance reports (RS256, bring-your-own-key)."""

from __future__ import annotations

import base64
import json
import subprocess
import pytest

from reporting.signing import (
    SigningError,
    canonical_body,
    sign_bytes,
    sign_report,
    verify_bytes,
    verify_report,
)


@pytest.fixture(scope="module")
def keypair(tmp_path_factory):
    """A real RSA keypair generated by OpenSSL (the deployment story, not a stub)."""
    directory = tmp_path_factory.mktemp("pki")
    private = directory / "priv.pem"
    public = directory / "pub.pem"
    subprocess.run(
        ["openssl", "genrsa", "-out", str(private), "2048"],
        check=True, capture_output=True, timeout=60,
    )
    subprocess.run(
        ["openssl", "rsa", "-in", str(private), "-pubout", "-out", str(public)],
        check=True, capture_output=True, timeout=60,
    )
    other = directory / "other.pem"
    other_pub = directory / "other.pub"
    subprocess.run(
        ["openssl", "genrsa", "-out", str(other), "2048"],
        check=True, capture_output=True, timeout=60,
    )
    subprocess.run(
        ["openssl", "rsa", "-in", str(other), "-pubout", "-out", str(other_pub)],
        check=True, capture_output=True, timeout=60,
    )
    return {"private": private, "public": public, "other_pub": other_pub, "dir": directory}


def test_sign_and_verify_roundtrip(keypair):
    data = b"canonical report body"
    signature = sign_bytes(data, keypair["private"])
    assert signature["alg"] == "RS256"
    assert signature["value"]
    assert verify_bytes(data, signature["value"], keypair["public"])["ok"] is True
    # any byte change breaks it
    assert verify_bytes(data + b"!", signature["value"], keypair["public"])["ok"] is False
    # wrong key breaks it
    assert verify_bytes(data, signature["value"], keypair["other_pub"])["ok"] is False


def test_signature_verifies_with_plain_openssl(keypair, tmp_path):
    """Interop proof: OpenSSL alone validates our signature — no CryptoScan code."""
    report = {"scan": {"id": "scan-1"}, "totals": {"findings": 2}, "generated_at": "2026-08-29"}
    sign_report(report, keypair["private"], key_id="ciso-2026")
    body = tmp_path / "body.json"
    body.write_bytes(canonical_body(report))
    sig = tmp_path / "report.sig"
    sig.write_bytes(base64.urlsafe_b64decode(report["signature"]["value"] + "=" * (-len(report["signature"]["value"]) % 4)))
    result = subprocess.run(
        ["openssl", "dgst", "-sha256", "-verify", str(keypair["public"]),
         "-signature", str(sig), str(body)],
        capture_output=True, timeout=60,
    )
    assert result.returncode == 0, result.stderr.decode()
    # and a tampered body fails the same independent check
    body.write_bytes(canonical_body(report) + b" ")
    tampered = subprocess.run(
        ["openssl", "dgst", "-sha256", "-verify", str(keypair["public"]),
         "-signature", str(sig), str(body)],
        capture_output=True, timeout=60,
    )
    assert tampered.returncode != 0


def test_sign_report_covers_whole_body_except_signature(keypair):
    report = {"totals": {"fail": 3}, "attestation": {"statement": "x"}, "report_hash": "ab" * 32}
    signed = sign_report(report, keypair["private"], key_id="k-1")
    assert signed["signature"]["key_id"] == "k-1"
    assert "verify" in signed["signature"]  # tells the auditor how to check it
    assert verify_report(signed, keypair["public"])["ok"] is True
    # mutating any covered member invalidates the signature
    signed["totals"]["fail"] = 0
    result = verify_report(signed, keypair["public"])
    assert result["ok"] is False and result["key_id"] == "k-1"
    # unsigned report is an honest failure, not a pass
    unsigned = {"totals": {"fail": 0}}
    assert verify_report(unsigned, keypair["public"]) == {
        "ok": False, "error": "report carries no signature", "backend": None,
    }


def test_canonical_body_is_order_independent(keypair):
    """JSON key order must not matter — the auditor canonicalizes the same bytes."""
    signed = sign_report({"a": 1, "b": {"c": 2}}, keypair["private"])
    reordered = {"b": {"c": 2}, "a": 1, "signature": signed["signature"]}
    assert canonical_body(reordered) == canonical_body({"a": 1, "b": {"c": 2}})
    assert verify_report(reordered, keypair["public"])["ok"] is True


def test_bad_keys_fail_loudly(tmp_path):
    garbage = tmp_path / "not-a-key.pem"
    garbage.write_text("-----BEGIN PRIVATE KEY-----\nnope\n-----END PRIVATE KEY-----\n")
    with pytest.raises(SigningError):
        sign_bytes(b"data", garbage)
    with pytest.raises(SigningError):
        sign_bytes(b"data", tmp_path / "missing.pem")


def test_signature_survives_json_roundtrip(keypair):
    """API responses travel as JSON — the signature must still verify after."""
    signed = sign_report({"scan": {"id": "s"}, "totals": {"findings": 1}}, keypair["private"])
    transported = json.loads(json.dumps(signed))
    assert verify_report(transported, keypair["public"])["ok"] is True


def test_inline_pem_recognized_before_path_probe(keypair):
    """A PEM passed as text must never be probed as a filesystem path.

    Regression: a random 2048-bit public-key PEM can (rarely) contain no '/'
    in its base64, making it one over-long path component — `Path(...).exists()`
    then raises OSError ENAMETOOLONG instead of recognizing the key material.
    """
    pem = keypair["public"].read_text()
    # Sanity: this PEM is long enough to exceed the 255-byte filename limit.
    assert len(pem) > 300
    signature = sign_bytes(b"deterministic inline-pem check", keypair["private"])
    assert signature["alg"] == "RS256"
    # The inline PEM must be recognized as key material, not probed as a path.
    result = verify_bytes(b"deterministic inline-pem check",
                          signature["value"], pem)
    assert result["ok"] is True


def test_read_key_deterministic_enametoolong_regression():
    """A '/'-free PEM string >255 chars must be treated as key text.

    Before the fix, `Path(pem).exists()` raised OSError ENAMETOOLONG because
    the whole PEM became one over-long path component (no '/' to split it).
    """
    from reporting.signing import _read_key

    no_slash_pem = "-----BEGIN PUBLIC KEY-----\n" + "A" * 400 + "\n-----END PUBLIC KEY-----\n"
    assert "/" not in no_slash_pem
    assert len(no_slash_pem) > 255
    assert _read_key(no_slash_pem) == no_slash_pem.encode("utf-8")
